import static org.junit.Assert.*;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;

public class UrlBuilderTest {

    @Test
    public void buildUrlFromValidUrlTest() {
        URL url = new URL("https://example.com/path?query=value#ref");
        UrlBuilder builder = new UrlBuilder(url);
        assertSame(UrlBuilder.class, builder.build().getClass());
    }

    @Test
    public void buildUrlFromInvalidUrlTest() {
        URL url = new URL("invalid-url");
        UrlBuilder builder = new UrlBuilder(url);
        assertNotNull(builder.build());
    }

    @Test
    public void appendKeyValWithValidConnectionTest() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new HashMap<String, String>().entrySet().iterator().next();
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        builder.appendKeyVal(kv);
        assertNotNull(builder.q);
    }

    @Test
    public void appendKeyValWithEmptyConnectionTest() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com"));
        builder.appendKeyVal(null);
        assertNotNull(builder.q);
        assertEquals(1, builder.q.length());
    }

    @Test
    public void decodePartEncodesSpacesCorrectlyTest() {
        String decoded = UrlBuilder.decodePart("%20");
        assertEquals(" ", decoded);
    }

    @Test
    public void normalizeQueryAddsPlusSignsCorrectlyTest() {
        String query = "query value";
        String normalized = UrlBuilder.normalizeQuery(query);
        assertEquals("query+value", normalized);
    }

    @Test
    public void normalizeRefReplacesSpacesWithPercent20sCorrectlyTest() {
        String ref = "# ref with spaces";
        String normalized = UrlBuilder.normalizeRef(ref);
        assertEquals("#%20ref%20with%20spaces", normalized);
    }
}
